arguments.command:
cd /app; python3 - <<'EOF'
import re,glob
files=glob.glob('/app/varsea/**/*',recursive=True)
for f in files:
    try: d=open(f,'rb').read()
    except: continue
    for pat in [rb'PASSWORD',rb'8XD',rb'W54',rb'launchcode']:
        for m in re.finditer(pat,d):
            s=max(0,m.start()-40); print(f,pat,hex(m.start()),repr(d[s:m.start()+60]))
EOF

