arguments.command:
cd /app; python3 - <<'EOF'
import re,glob
for f in glob.glob('/app/varsea/**/*',recursive=True):
    try: d=open(f,'rb').read()
    except: continue
    for m in re.finditer(rb'[A-Z0-9]{9,}',d):
        print(f,hex(m.start()),m.group().decode())
EOF

